package com.library.server.controller; import com.library.common.annotation.RequireRole; import com.library.common.constant.RoleConstant; import com.library.common.model.*; import com.library.pojo.entity.Reader; import com.library.server.service.ReaderService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/readers") @RequireRole(RoleConstant.ADMIN) public class ReaderController {private final ReaderService service;public ReaderController(ReaderService service){this.service=service;} @GetMapping public ApiResult<PageResult<Reader>> page(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int size,@RequestParam(required=false) String keyword){return ApiResult.success(service.page(keyword,page,size));} @GetMapping("/{id}") public ApiResult<Reader> get(@PathVariable Long id){return ApiResult.success(service.get(id));} @PostMapping public ApiResult<Void> save(@RequestBody Reader x){service.save(x);return ApiResult.success();} @PutMapping public ApiResult<Void> update(@RequestBody Reader x){service.update(x);return ApiResult.success();} @DeleteMapping("/{id}") public ApiResult<Void> delete(@PathVariable Long id){service.delete(id);return ApiResult.success();}}
